source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            queue = [(r, c)]
            seen.add((r, c))
            component = []
            for y, x in queue:
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 3 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        queue.append((yy, xx))
            boxes.append((min(y for y, x in component), max(y for y, x in component),
                          min(x for y, x in component), max(x for y, x in component)))

    output = [row[:] for row in grid]
    for r0, r1, c0, c1 in boxes:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if grid[r][c] == 2:
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            y, x = r + dy, c + dx
                            if 0 <= y < h and 0 <= x < w and (dy, dx) != (0, 0) and output[y][x] != 2:
                                output[y][x] = 1
    return output
'''
